const CONFIG = {
  apiCollectionId: 1788379458,
  apiMethod: "POST",
  apiUrl: "https://aria.tapestry.com/api/chat",
  collectionName: "ARIA Tapestry Chat (agentic)",
  hostName: "aria-manual.ai-agent.aria-tapestry",
};

function apiInfoKey() {
  return {
    _t: "com.akto.dto.ApiInfo$ApiInfoKey",
    apiCollectionId: CONFIG.apiCollectionId,
    method: CONFIG.apiMethod,
    url: CONFIG.apiUrl,
  };
}

function deletePriorRuns() {
  const names = [SEED.runName, "aria-history-replay-2026-10-05"];
  const runs = db.testing_run.find({ name: { $in: names } }).toArray();
  runs.forEach(function (run) {
    const results = db.testing_run_result.find({ testRunId: run._id }).toArray();
    const convIds = [];
    results.forEach(function (result) {
      (result.testResults || []).forEach(function (turn) {
        if (turn.conversationId) convIds.push(turn.conversationId);
      });
      db.vulnerable_testing_run_results.deleteOne({ _id: result._id });
    });
    if (convIds.length) {
      printjson(db.agent_conversation_results.deleteMany({ conversationId: { $in: convIds } }));
    }
    printjson(db.testing_run_result.deleteMany({ testRunId: run._id }));
    printjson(db.testing_run_result_summaries.deleteMany({ testingRunId: run._id }));
    printjson(db.testing_run.deleteOne({ _id: run._id }));
    print("Removed prior run " + run._id);
  });
}

function ensureArgusApiCollection(now) {
  const collId = CONFIG.apiCollectionId;
  const tag = (keyName, value) => ({
    lastUpdatedTs: now,
    keyName: keyName,
    value: value,
    source: "USER",
  });
  const coll = {
    _id: collId,
    name: CONFIG.collectionName,
    displayName: CONFIG.collectionName,
    hostName: CONFIG.hostName,
    startTs: now,
    urls: [CONFIG.apiUrl],
    vxlanId: 0,
    deactivated: false,
    redact: false,
    sampleCollectionsDropped: false,
    isOutOfTestingScope: false,
    automated: false,
    tagsList: [tag("source", "ENDPOINT"), tag("gen-ai", "ARIA"), tag("ai-agent", "aria-tapestry")],
  };
  const existing = db.api_collections.findOne({ _id: collId });
  if (existing) {
    print("api_collections " + collId + " exists — merging Argus tags");
    printjson(
      db.api_collections.updateOne(
        { _id: collId },
        {
          $set: {
            name: coll.name,
            displayName: coll.displayName,
            hostName: coll.hostName,
            urls: coll.urls,
            tagsList: coll.tagsList,
          },
        }
      )
    );
  } else {
    print("Insert api_collections (Argus / agentic-assets)");
    printjson(db.api_collections.insertOne(coll));
  }
  const apiInfoId = { apiCollectionId: collId, url: CONFIG.apiUrl, method: CONFIG.apiMethod };
  if (!db.api_info.findOne({ _id: apiInfoId })) {
    printjson(
      db.api_info.insertOne({
        _id: apiInfoId,
        collectionIds: [collId],
        lastSeen: now,
        lastUpdated: now,
        discoveredTimestamp: now,
        apiAccessTypes: [],
        riskScore: 0,
      })
    );
  }
}

function upsertTemplates() {
  SEED.templates.forEach(function (template) {
    printjson(
      db.yaml_templates.replaceOne(
        { _id: template._id },
        {
          _id: template._id,
          author: "AKTO",
          content: template.content,
          createdAt: template.createdAt,
          hash: template.hash,
          inactive: false,
          info: template.info,
          updatedAt: template.updatedAt,
        },
        { upsert: true }
      )
    );
  });
  print("yaml_templates upserted: " + SEED.templates.length + " (author AKTO, no source)");
}

function resolveConfigId() {
  const want = SEED.testSubCategoryList;
  const found = db.testing_run_config.find({ testSubCategoryList: want }).limit(1).toArray();
  if (found.length) {
    print("Reusing testing_run_config " + found[0]._id);
    return found[0]._id;
  }
  let id = SEED.testIdConfig;
  while (db.testing_run_config.findOne({ _id: id })) id += 1;
  print("Insert testing_run_config " + id);
  printjson(
    db.testing_run_config.insertOne({
      _id: id,
      testSubCategoryList: want,
      cleanUp: false,
    })
  );
  return id;
}

function conversationDoc(test, turn) {
  const doc = {
    _id: ObjectId(turn.convObjectId),
    conversation: ["## Orchestrator Response\n\n" + turn.response],
    conversationId: test.conversationId,
    finalSentPrompt: turn.user,
    prompt: turn.user,
    response: turn.response,
    timestamp: turn.end,
    toolsMetadata: {},
    validation: !turn.last,
  };
  if (!turn.last) {
    doc.validationMessage = "null";
    doc.remediationMessage = "null";
  }
  return doc;
}

function buildResult(test, runId, summaryId) {
  return {
    _id: ObjectId(test.resultObjectId),
    _t: "com.akto.dto.testing.TestingRunResult",
    apiInfoKey: apiInfoKey(),
    confidencePercentage: 100,
    endTimestamp: test.endTimestamp,
    rerun: false,
    singleTypeInfos: [],
    startTimestamp: test.startTimestamp,
    testResults: test.turns.map(function (turn) {
      return {
        _t: "com.akto.dto.testing.TestResult",
        confidence: test.severity,
        conversationId: test.conversationId,
        errors: [],
        message: turn.message,
        percentageMatch: 100,
        requiresConfig: false,
        resultTypeAgentic: true,
        vulnerable: false,
      };
    }),
    testRunId: runId,
    testRunResultSummaryId: summaryId,
    testSubType: test.testSubType,
    testSuperType: test.testSuperType,
    vulnerable: false,
  };
}

deletePriorRuns();
ensureArgusApiCollection(SEED.schedule);
upsertTemplates();
const testIdConfig = resolveConfigId();

const runId = ObjectId(SEED.runObjectId);
const summaryId = ObjectId(SEED.summaryObjectId);
const n = SEED.tests.length;

print("Insert testing_run");
printjson(
  db.testing_run.insertOne({
    _id: runId,
    _t: "com.akto.dto.testing.TestingRun",
    allowedMiniTestingServiceNames: ["tapestry-external-agentic-testing-2"],
    dashboardContext: "AGENTIC",
    doNotMarkIssuesAsFixed: true,
    endTimestamp: SEED.end,
    maxAgentTokens: -1,
    maxConcurrentRequests: 1,
    name: SEED.runName,
    newTestRun: true,
    periodInSeconds: 0,
    pickedUpTimestamp: SEED.pickedUp,
    runAutomatedTests: false,
    scheduleTimestamp: SEED.schedule,
    selectedSlackChannelId: 0,
    sendMsTeamsAlert: false,
    sendPendingTestsWebhookTimestamp: 0,
    sendSlackAlert: false,
    state: "COMPLETED",
    testIdConfig: testIdConfig,
    testRunTime: 10800,
    testingEndpoints: {
      _t: "com.akto.dto.testing.CollectionWiseTestingEndpoints",
      apiCollectionId: CONFIG.apiCollectionId,
      operator: "AND",
      type: "COLLECTION_WISE",
    },
    userEmail: "shivansh@akto.io",
    miniTestingServiceName: "tapestry-external-agentic-testing-2",
  })
);

print("Insert summary");
printjson(
  db.testing_run_result_summaries.insertOne({
    _id: summaryId,
    state: "COMPLETED",
    testingRunId: runId,
    isNewTestingSummary: true,
    startTimestamp: SEED.summaryStart,
    testInitiatedCount: n,
    totalApis: 1,
    testResultsCount: n,
    countIssues: { CRITICAL: 0, HIGH: 0, LOW: 0, MEDIUM: 0 },
    endTimestamp: SEED.end,
  })
);

SEED.tests.forEach(function (test) {
  test.turns.forEach(function (turn) {
    printjson(db.agent_conversation_results.insertOne(conversationDoc(test, turn)));
  });
  print("Insert result " + test.testSubType);
  printjson(db.testing_run_result.insertOne(buildResult(test, runId, summaryId)));
});

print("Done. Run " + runId + "  summary " + summaryId);
print("Tests: " + n + "  issues: 0  vulnerable results: 0");
print("Api collection id: " + CONFIG.apiCollectionId);
SEED.tests.forEach(function (test) {
  print(
    "  " +
      test.testSubType +
      " " +
      test.severity +
      " " +
      new Date(test.startTimestamp * 1000).toISOString() +
      " -> " +
      new Date(test.endTimestamp * 1000).toISOString()
  );
});
